 "content": "def transform(grid):
    """Duplicate the outer rows and columns of a 3x3 grid."""
    row_factors = [2, 1, 2]
    col_factors = [2, 1, 2]
    out = []
    for r, row in enumerate(grid):
        expanded_row = []
        for c, value in enumerate(row):
            expanded_row.extend([value] * col_factors[c])
        for _ in range(row_factors[r]):
            out.append(expanded_row[:])
    return out
